func buildFilterPredicate(entity string, path []string, operator FilterOperator, raw json.RawMessage) (FilterPredicate, error) {
	switch entity {

	case "StoreApp":
		return buildStoreAppFilterPredicate(path, operator, raw)

	case "StoreGenre":
		return buildStoreGenreFilterPredicate(path, operator, raw)

	case "WywwGenre":
		return buildWywwGenreFilterPredicate(path, operator, raw)

	case "WywwMovie":
		return buildWywwMovieFilterPredicate(path, operator, raw)

	}

	return nil, errors.New("could not generate any predicate")
}
